import functools

def curry(func):
    """
    Curries a given function, allowing it to be called with multiple arguments one at a time.

    Parameters:
    func (callable): The function to curry.

    Returns:
    callable: A curried version of the given function.
    """

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if len(args) == 0 and len(kwargs) == 0:
            return func()
        elif len(args) > 0 and len(kwargs) == 0:
            return functools.reduce(func, args)
        else:
            return functools.reduce(lambda acc, arg: func(acc, arg), args, kwargs.popitem())

    return wrapper
